// Generated by Cypress Author on 2026-10-08.
import type { ApiError, MeResponse } from '../../../../backend/src/types/api';
import SpotifyProfile from '../../../src/components/SpotifyProfile';


const me: MeResponse = {
  clerkUserId: 'user_test',
  spotify: {
    id: 'spotify-test',
    displayName: 'Test Listener',
    email: 'listener@example.test',
    country: 'BG',
    product: 'premium',
    // No avatar: the snapshot must not depend on an external image.
    imageUrl: null,
    profileUrl: 'https://open.spotify.com/user/spotify-test',
  },
};

describe('SpotifyProfile', () => {
  it('loads the profile → shows name, details and Spotify link', () => {
    cy.intercept('GET', '/api/me', { body: me }).as('me');
    cy.mount(<SpotifyProfile />);
    cy.wait('@me');

    cy.contains('h2', 'Test Listener').should('be.visible');
    cy.contains('button', 'My profile').should('be.visible');
    cy.get('section[aria-label="Spotify profile"]').matchImage();
    cy.contains('button', 'My profile').click();
    cy.get('[role="dialog"]').should('be.visible').and('contain.text', me.spotify.email);
    cy.contains('a', 'Open in Spotify').should('have.attr', 'href', me.spotify.profileUrl);
    cy.get('[role="dialog"]').matchImage();
    cy.contains('button', 'Close').click();
    cy.get('[role="dialog"]').should('not.exist');
    cy.contains('button', 'My profile').should('have.focus');
    cy.contains('button', 'My profile').click();
    cy.get('[role="dialog"]').should('be.visible');
    cy.get('body').type('{esc}');
    cy.get('[role="dialog"]').should('not.exist');
  });

  it('API fails → shows the error alert', () => {
    cy.intercept('GET', '/api/me', { statusCode: 401, body: { error: 'Unauthorized' } satisfies ApiError }).as('me');
    cy.mount(<SpotifyProfile />);
    cy.wait('@me');

    cy.get('[role="alert"]').should('contain.text', 'Unauthorized').matchImage();
  });

  it('profile is pending → shows the loading message', () => {
    // Hold the response until the loading snapshot has been taken.
    let release: (() => void) | undefined;
    cy.intercept('GET', '/api/me', (request) => new Cypress.Promise<void>((resolve) => {
      release = () => { request.reply({ body: me }); resolve(); };
    })).as('me');
    cy.mount(<SpotifyProfile />);
    cy.get('[role="status"]').should('contain.text', 'Loading your Spotify profile').matchImage();
    cy.then(() => release?.());
    cy.wait('@me');
  });

  it('optional details are missing → shows friendly fallbacks in the dialog', () => {
    cy.intercept('GET', '/api/me', { body: { ...me, spotify: { id: 'spotify-test', displayName: null, imageUrl: null, profileUrl: null } } satisfies MeResponse }).as('me');
    cy.mount(<SpotifyProfile />);
    cy.wait('@me');
    cy.contains('h2', 'Music lover').should('be.visible');
    cy.get('section[aria-label="Spotify profile"]').matchImage();
    cy.contains('button', 'My profile').click();
    cy.get('[role="dialog"]').should('contain.text', 'Not shared');
    cy.contains('a', 'Open in Spotify').should('not.exist');
    cy.get('[role="dialog"]').matchImage();
  });

  it('mobile profile → keeps the card and dialog readable', () => {
    cy.viewport(390, 844);
    cy.intercept('GET', '/api/me', { body: me }).as('me');
    cy.mount(<SpotifyProfile />);
    cy.wait('@me');
    cy.contains('h2', 'Test Listener').should('be.visible');
    cy.get('section[aria-label="Spotify profile"]').matchImage();
    cy.contains('button', 'My profile').click();
    cy.get('[role="dialog"]').should('be.visible').and('contain.text', 'listener@example.test').matchImage();
    cy.contains('button', 'Close').should('be.visible');
  });
});
